import {expect,test} from "vitest";
import {h} from "./miniReact";
test("h",()=>{
  expect(h("ul",null,[h("li",null,"a"),h("li",null,"b")],"c").props.children).toHaveLength(3);
  expect(h("p",null)).toEqual({type:"p",props:{children:[]}});
});

